using B2B.Erp.Api.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace B2B.Erp.Api.Data.Configurations;

public class BankBinConfiguration : IEntityTypeConfiguration<BankBin>
{
    public void Configure(EntityTypeBuilder<BankBin> builder)
    {
        builder.ToTable("BankBins");

        builder.HasKey(b => b.Id);

        builder.Property(b => b.BankCode)
            .IsRequired()
            .HasMaxLength(10);

        builder.Property(b => b.BankCode)
            .HasColumnName("BANKA_KODU");

        builder.Property(b => b.Bin6)
            .IsRequired()
            .HasMaxLength(6);

        builder.Property(b => b.Bin6)
            .HasColumnName("BIN6");

        builder.Property(b => b.CardType1)
            .HasMaxLength(20);

        builder.Property(b => b.CardType1)
            .HasColumnName("TIP1");

        builder.Property(b => b.CardType2)
            .HasMaxLength(30);

        builder.Property(b => b.CardType2)
            .HasColumnName("TIP2");

        builder.Property(b => b.HasInstallment)
            .HasColumnName("TAKSIT");

        builder.Property(b => b.InstallmentBankCode)
            .HasMaxLength(10);

        builder.Property(b => b.InstallmentBankCode)
            .HasColumnName("TAKSIT_BANKA_KODU");

        builder.HasIndex(b => b.Bin6);

        SeedData(builder);
    }

